EXPORT ZZT_CROP() BEGIN
Base:=3; Bits:=32; Signed:=0;
LOCAL out:={},w,h,x,y,row,r;

DIMGROB_P(G2,3,3,#0h); FOR y FROM 0 TO 2 DO FOR x FROM 0 TO 2 DO PIXON_P(G2,x,y,(x+1+10*y)*#10000h); END; END;
r:=0; IFERR r:=BLIT_P(G2,1,0,G2,0,0,3,3); THEN r:="error"; END;
w:=GROBW_P(G2); h:=GROBH_P(G2); row:={};
IF w*h<40 AND w*h>0 THEN FOR y FROM 0 TO h-1 DO FOR x FROM 0 TO w-1 DO row:=CONCAT(row,{FLOOR(B→R(GETPIX_P(G2,x,y))/65536)}); END; END; END;
out:=CONCAT(out,{{r,w,h,row}});
DIMGROB_P(G2,3,3,#0h); FOR y FROM 0 TO 2 DO FOR x FROM 0 TO 2 DO PIXON_P(G2,x,y,(x+1+10*y)*#10000h); END; END;
r:=0; IFERR r:=BLIT_P(G2,0,1,G2,0,0,3,2); THEN r:="error"; END;
w:=GROBW_P(G2); h:=GROBH_P(G2); row:={};
IF w*h<40 AND w*h>0 THEN FOR y FROM 0 TO h-1 DO FOR x FROM 0 TO w-1 DO row:=CONCAT(row,{FLOOR(B→R(GETPIX_P(G2,x,y))/65536)}); END; END; END;
out:=CONCAT(out,{{r,w,h,row}});
DIMGROB_P(G2,3,3,#0h); FOR y FROM 0 TO 2 DO FOR x FROM 0 TO 2 DO PIXON_P(G2,x,y,(x+1+10*y)*#10000h); END; END;
r:=0; IFERR r:=BLIT_P(G2,0,0,3,3,G2,1,0,3,3); THEN r:="error"; END;
w:=GROBW_P(G2); h:=GROBH_P(G2); row:={};
IF w*h<40 AND w*h>0 THEN FOR y FROM 0 TO h-1 DO FOR x FROM 0 TO w-1 DO row:=CONCAT(row,{FLOOR(B→R(GETPIX_P(G2,x,y))/65536)}); END; END; END;
out:=CONCAT(out,{{r,w,h,row}});
DIMGROB_P(G2,3,3,#0h); FOR y FROM 0 TO 2 DO FOR x FROM 0 TO 2 DO PIXON_P(G2,x,y,(x+1+10*y)*#10000h); END; END;
r:=0; IFERR r:=BLIT_P(G2,0,0,3,3,G2,0,0,2,2,0,128); THEN r:="error"; END;
w:=GROBW_P(G2); h:=GROBH_P(G2); row:={};
IF w*h<40 AND w*h>0 THEN FOR y FROM 0 TO h-1 DO FOR x FROM 0 TO w-1 DO row:=CONCAT(row,{FLOOR(B→R(GETPIX_P(G2,x,y))/65536)}); END; END; END;
out:=CONCAT(out,{{r,w,h,row}});
RETURN out; END;

EXPORT RASTERCONTROL() BEGIN
  Base:=3; Bits:=32; Signed:=0;
  RECT_P(0,0,319,239,#FFFFFFh,#FFFFFFh);
  LOCAL x,y,out:={};
  FOR y FROM 0 TO 3 DO
    FOR x FROM 0 TO 4 DO
      PIXON_P(x,y,RGB(10*x+1,20*y+3,31*(x+y)));
    END;
  END;
  BLIT_P(G0,1,1,5,4,G0,0,0,3,3,RGB(11,23,62),160);
  FOR y FROM 0 TO 3 DO
    FOR x FROM 0 TO 4 DO
      out:=CONCAT(out,{B→R(GETPIX_P(G0,x,y))});
    END;
  END;
  RETURN out;
END;

EXPORT ZZT_EMPTY() BEGIN LOCAL r,out:={};
DIMGROB_P(G1,3,3,#FF0000h);DIMGROB_P(G2,5,2,#C00000h);
r:=1; IFERR SUBGROB_P(G1,2,1,2,3,G2); THEN r:=0; END;
out:=CONCAT(out,{{r,GROBW_P(G2),GROBH_P(G2)}});
DIMGROB_P(G1,3,3,#FF0000h);DIMGROB_P(G2,5,2,#C00000h);
r:=1; IFERR SUBGROB_P(G1,1,2,3,2,G2); THEN r:=0; END;
out:=CONCAT(out,{{r,GROBW_P(G2),GROBH_P(G2)}});
DIMGROB_P(G1,3,3,#FF0000h);DIMGROB_P(G2,5,2,#C00000h);
r:=1; IFERR SUBGROB_P(G1,3,3,G2); THEN r:=0; END;
out:=CONCAT(out,{{r,GROBW_P(G2),GROBH_P(G2)}});
DIMGROB_P(G1,3,3,#FF0000h);DIMGROB_P(G2,5,2,#C00000h);
r:=1; IFERR SUBGROB_P(G1,2,1,1,3,G2); THEN r:=0; END;
out:=CONCAT(out,{{r,GROBW_P(G2),GROBH_P(G2)}});
DIMGROB_P(G1,3,3,#FF0000h);DIMGROB_P(G2,5,2,#C00000h);
r:=1; IFERR SUBGROB_P(G1,0,0,0,2,G1); THEN r:=0; END;
out:=CONCAT(out,{{r,GROBW_P(G1),GROBH_P(G1)}});
DIMGROB_P(G1,3,3,#FF0000h);DIMGROB_P(G2,5,2,#C00000h);
r:=1; IFERR SUBGROB_P(G1,3,3,G2);DIMGROB_P(G2,1,1,#A00000h); THEN r:=0; END;
out:=CONCAT(out,{{r,GROBW_P(G2),GROBH_P(G2)}});
RETURN out; END;
